//! Railgun cryptography primitives (Track 2 Phase B).
//!
//! This module implements the Rust counterparts to every primitive that
//! `@railgun-community/engine` exposes for wallet key derivation and note
//! handling. Each submodule is cross-validated bit-for-bit against the
//! JSON test vectors at `crates/vault-signer/tests/fixtures/railgun_vectors.json`,
//! which are generated by `apps/railgun-vector-generator` running the
//! upstream engine over a fixed mnemonic.
//!
//! Module layout follows the primitive boundaries — each piece has its own
//! vector subset and can be ported independently:
//!
//! - [`poseidon`] — Poseidon over BN254 (`light-poseidon` wrapper)
//! - [`bech32_address`] — `0zk1...` bech32m address encoding
//! - [`aes_gcm`] — AES-256-GCM with Railgun's non-standard 16-byte IV
//! - [`x25519`] — Viewing key + Railgun ECDH shared-key derivation
//! - [`babyjubjub`] — Baby Jubjub curve ops + point packing
//! - [`bip32`] — Railgun's custom hardened-only BIP32 over `babyjubjub seed`
//! - [`eddsa`] — iden3 EdDSA-Poseidon signing + verification
//! - [`wallet`] — High-level `deriveNodes` / nullifier / master public key

pub mod aes_gcm;
pub mod babyjubjub;
pub mod bech32_address;
pub mod bip32;
pub mod eddsa;
pub mod poseidon;
pub mod wallet;
pub mod x25519;

#[cfg(test)]
mod test_vectors;
